class Solution {
    int minimumMovesToSortArray(int[] arr) {
        int n = arr.length;
        long cap = arr[n - 1], ops = 0;
        for (int i = n - 2; i >= 0; i--) {
            if (arr[i] <= cap) cap = arr[i];
            else {
                long k = (arr[i] + cap - 1) / cap;
                ops += k - 1;
                cap = arr[i] / k;
            }
        }
        return (int) ops;
    }
}
